"""Finding the stretches of opening hours that nobody covers."""

from typing import Iterable, List

from hourglass.models import Span
from hourglass.merging import merge_spans

def _clock(minute: int) -> str:
    return f"{minute // 60:02d}:{minute % 60:02d}"

def find_gaps(worked: Iterable[Span], opening: Span) -> List[str]:
    """One label per uncovered stretch, such as "gap 12:00-13:00 (60 min)".

    Raises ValueError when a worked span falls outside opening hours.
    """
    spans = list(worked)
    for span in spans:
        if span.start < opening.start or span.end > opening.end:
            raise ValueError(f"span outside opening hours: {span}")

    labels = []
    cursor = opening.start
    for span in merge_spans(spans):
        if span.start > cursor:
            labels.append(_label(Span(cursor, span.start)))
        cursor = span.end
    if cursor < opening.end:
        labels.append(_label(Span(cursor, opening.end)))
    return labels

def _label(stretch: Span) -> str:
    return f"gap {_clock(stretch.start)}-{_clock(stretch.end)} ({stretch.minutes} min)"

