# owner: platform
import unittest

from hourglass.models import Span
from hourglass.gaps import find_gaps

class GapTests(unittest.TestCase):
    opening = Span(8 * 60, 17 * 60)

    def test_middle_gap(self):
        worked = [Span(8 * 60, 12 * 60), Span(13 * 60, 17 * 60)]
        self.assertEqual(find_gaps(worked, self.opening), ["gap 12:00-13:00 (60 min)"])

    def test_nobody_worked(self):
        self.assertEqual(find_gaps([], self.opening), ["gap 08:00-17:00 (540 min)"])

    def test_full_cover_with_overlap(self):
        worked = [Span(8 * 60, 13 * 60), Span(12 * 60, 17 * 60)]
        self.assertEqual(find_gaps(worked, self.opening), [])

    def test_edges(self):
        worked = [Span(9 * 60, 16 * 60)]
        self.assertEqual(
            find_gaps(worked, self.opening),
            ["gap 08:00-09:00 (60 min)", "gap 16:00-17:00 (60 min)"]
        )

    def test_outside_opening_hours(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(7 * 60, 9 * 60)], self.opening)
